def validate_outputs(root):
    root = Path(root)
    state = json.loads((root/"deliverables/snapshots/evidence/planning-state.json").read_text())
    model, options, selected, run_id = state["model"], state["options"], state["selected_option"], state["run_id"]
    errors, checks = [], []
    for name in ARTIFACTS:
        path = root/"deliverables"/name
        if not path.is_file() or not path.stat().st_size:
            errors.append("Missing/empty artifact:"+name)
    if errors:
        return {"valid": False, "errors": errors, "checks": checks}
    with (root/"deliverables/vendor-comparison.csv").open(newline="") as handle:
        rows = list(csv.DictReader(handle))
    expected = {x["option_id"]: x for x in options}
    if len(rows) != len(expected) or {r["option_id"] for r in rows} != set(expected):
        errors.append("CSV option identities mismatch")
    for row in rows:
        option = expected.get(row["option_id"])
        if not option:
            continue
        for key in ("cost_twd", "planning_people"):
            if row[key] != (str(option[key]) if option[key] is not None else ""):
                errors.append("CSV value mismatch:"+row["option_id"]+":"+key)
        if json.loads(row["quote_ids"]) != option["quote_ids"] or row["feasibility"] != option["feasibility"] or row["approval_status"] != "pending":
            errors.append("CSV quote/feasibility/approval mismatch")
    calendar = Calendar.from_ical((root/"deliverables/event-calendar.ics").read_bytes())
    if str(calendar.get("VERSION")) != "2.0" or str(calendar.get("METHOD")) != "PUBLISH":
        errors.append("Invalid calendar envelope")
    uids, blocks, source_ids = set(), [], set()
    for event in list(calendar.walk("VEVENT"))+list(calendar.walk("VTODO")):
        uid = str(event.get("UID"))
        if uid in uids or not event.get("DTSTAMP") or event.get("ATTENDEE"):
            errors.append("Calendar UID/stamp/attendee failure")
        uids.add(uid)
        if event.name == "VEVENT":
            start, end = event["DTSTART"].dt, event["DTEND"].dt
            if start.tzinfo is None or end.tzinfo is None or end <= start or str(event.get("STATUS")) != "TENTATIVE":
                errors.append("Calendar event timestamp/status failure")
            if str(event.get("X-RECORD-KIND")) == "programme":
                blocks.append((start, end))
        else:
            if event["DUE"].dt.tzinfo is None or str(event.get("STATUS")) != "NEEDS-ACTION":
                errors.append("Calendar deadline failure")
        if event.get("X-SOURCE-RECORD"):
            source_ids.add(str(event["X-SOURCE-RECORD"]))
        if run_id not in str(event.get("DESCRIPTION")):
            errors.append("Calendar run binding mismatch")
    for before, after in zip(sorted(blocks), sorted(blocks)[1:]):
        if before[1] > after[0]:
            errors.append("Actual ICS programme overlap")
    if model["programme"] and source_ids != {r["constraint_id"] for r in model["calendar"]}:
        errors.append("Calendar source record lost")
    for name in ("event-plan.md", "draft-communications.md"):
        text = (root/"deliverables"/name).read_text()
        if run_id not in text or "UNSENT" not in text or str(model["people"]) not in text or "pending" not in text:
            errors.append("Draft run/headcount/approval binding:"+name)
    errors += programme_checks(model) if model["programme"] else []
    # Independent identities/quantity checks on actual ICS rather than writer state alone.
    demos = [ev for ev in calendar.walk("VEVENT") if re_demo(str(ev.get("SUMMARY")))]
    if model["programme"] and (len(demos) != len(model["demo_ids"]) or sum(int((ev["DTEND"].dt-ev["DTSTART"].dt).total_seconds()/60) for ev in demos) != len(model["demo_ids"])*(model["demo_minutes"]+model["changeover_minutes"])):
        errors.append("Actual ICS demo count/durations mismatch")
    checks += ["Reopened CSV matches option identities,amounts,headcounts,quotes and pending approvals", "Parsed ICS envelope,UIDs,timezones,positive intervals,deadline,source records,run binding andprogramme overlap", "Reopened Markdown run/headcount/pending-draft bindings", "Actual ICS demo identities and duration total"]
    return {"valid": not errors, "errors": errors, "checks": checks}


def re_demo(value):
    import re
    return bool(re.search(r"\bDEMO-\d{2}\b", value))

