        programme.append({"event_id": identity, "summary": summary, "start_at": a.isoformat(), "end_at": b.isoformat(), "duration_minutes": int((b-a).total_seconds()/60), "kind": kind, "dependencies": dependency or [], "status": "TENTATIVE", **extra})
